def stream_rows(resource, transform):
    # Generator body does not run until the first next(), so construction and
    # close() on an unstarted generator perform no read and no close.
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            yield transform(row)
    except GeneratorExit:
        # Explicit close() or garbage collection while suspended at a yield.
        # No iteration/transform error is active, so cleanup errors propagate.
        resource.close()
        raise
    except BaseException:
        # Iteration or transform error: the original error must win over any
        # cleanup error, so the cleanup error is discarded here.
        _close_discarding_error(resource)
        raise
    else:
        # Exhaustion: no error is active, so cleanup errors propagate.
        resource.close()


def _close_discarding_error(resource):
    try:
        resource.close()
    except Exception:
        pass
EOF
cat > src/consumer.py <<'EOF'
from .service import stream_rows

def take(resource, transform, limit):
    if limit == 0:
        # Do not create or start the stream at all.
        return []
    stream = stream_rows(resource, transform)
    result = []
    try:
        for row in stream:
            result.append(row)
            if len(result) >= limit:
                break
    finally:
        # Early exit (limit reached): closes the resource once.
        # Exhaustion or error: the stream already closed it; close() is a no-op.
        stream.close()
    return result
EOF
